from pricing import compute_discount

def final_total(items: list[float], rate: float, tax_rate: float) -> float:
    subtotal = sum(items)
    discount = compute_discount(subtotal, rate)
    return round((subtotal + discount) * (1.0 + tax_rate), 2)

