export interface Receipt { region: string; total: number; }
export function formatReceipt(r: Receipt): string {
  return `${r.region.trim().toLowerCase()}: $${r.total.toFixed(2)}`;
}

files.ledger.ts:
export interface Entry { kind: 'credit' | 'debit'; amount: number; }
export function netBalance(entries: Entry[]): number {
  return entries.reduce((acc, e) => acc + e.amount, 0);
}

